// Signs release APKs with the owner's keystore (BUILD_AND_RELEASE.md § 1–2, ADR-014).
// android/ is regenerated by prebuild, so the signing config is added here instead of by
// hand. Passwords and the keystore path live in %USERPROFILE%\.gradle\gradle.properties
// (outside the repo):
//   HISAAB_STORE_FILE, HISAAB_STORE_PASSWORD, HISAAB_KEY_ALIAS, HISAAB_KEY_PASSWORD
// A release build without them fails, so a debug-signed APK can never be handed out.

const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// hisaab-release-signing';

const SIGNING_CONFIG = `signingConfigs {
        ${MARKER}
        release {
            if (project.hasProperty('HISAAB_STORE_FILE')) {
                storeFile file(HISAAB_STORE_FILE)
                storePassword HISAAB_STORE_PASSWORD
                keyAlias HISAAB_KEY_ALIAS
                keyPassword HISAAB_KEY_PASSWORD
            }
        }`;

const RELEASE_SIGNING = `if (!project.hasProperty('HISAAB_STORE_FILE')) {
                throw new GradleException('Release signing: HISAAB_STORE_FILE etc. missing from ~/.gradle/gradle.properties (docs/09-config/BUILD_AND_RELEASE.md)')
            }
            signingConfig signingConfigs.release`;

function addReleaseSigning(contents) {
  if (contents.includes(MARKER)) return contents;
  const withConfig = contents.replace(/signingConfigs\s*\{/, SIGNING_CONFIG);
  const withRelease = withConfig.replace(
    /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/,
    `$1${RELEASE_SIGNING}`,
  );
  if (withConfig === contents || withRelease === withConfig) {
    throw new Error(
      'withReleaseSigning: android/app/build.gradle template changed; update the plugin',
    );
  }
  return withRelease;
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    cfg.modResults.contents = addReleaseSigning(cfg.modResults.contents);
    return cfg;
  });
};
module.exports.addReleaseSigning = addReleaseSigning;
